    /**
     * Method to retrieve the Placement via PlacementFetchOneSummary
     * @param 	summary PlacementFetchOneSummary 
     * @return 	PlacementFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Placement getPlacement( PlacementFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PlacementFetchOneSummary arg cannot be null" );
    	
    	Placement entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Placement
        	// --------------------------------------
        	CompletableFuture<Placement> futureEntity = queryGateway.query(new FindPlacementQuery( new LoadPlacementFilter( summary.getPlacementId() ) ), ResponseTypes.instanceOf(Placement.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Placement with id " + summary.getPlacementId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


